31:       if (mountedRef.current && requestId === requestIdRef.current) {
32:         setError(
33:           refreshError instanceof Error
34:             ? refreshError.message
35:             : 'Не удалось обновить рыночные данные.',
36:         );
37:       }
38:     } finally {
39:       if (mountedRef.current && requestId === requestIdRef.current) {
40:         setLoading(false);
41:       }
42:     }
43:   }, []);
